    ),
    (
        "kGlm52FmhaSparseLongQ8",
        "fmhaSm100fKernel_QkvE4m3OBfloat16HQk576HV512HVPerCta128PagedKvDenseStaticTokenSparseP1MultiCtasKvVarSeqQ8Kv128StaticSwapsAbForGen.cubin",
    ),
