fn triton_target(sm_targets: &[String]) -> String {
    let max_sm = sm_targets
        .iter()
        .filter_map(|sm| sm_numeric_prefix(sm))
        .max()
        .expect("expected at least one CUDA SM target for Triton AOT");

    if sm_targets.len() > 1 {
        println!(
            "cargo:warning=Triton AOT currently emits one cubin per kernel spec; using highest detected target sm_{max_sm}. Set PEGAINFER_CUDA_SM to pin one target explicitly."
        );
    }

    format!("cuda:{max_sm}:32")
}

fn sm_numeric_prefix(sm: &str) -> Option<u32> {
    let digits = sm
        .chars()
        .take_while(char::is_ascii_digit)
        .collect::<String>();
    if digits.is_empty() {
        None
    } else {
        digits.parse::<u32>().ok()
    }
}

fn generate_triton_artifacts(
    python: &str,
    out_dir: &Path,
    triton_target: &str,
    spec: &TritonKernelSpec,
) -> (String, PathBuf) {
    let root = crate_root();
    let generator_path = root.join("tools/triton/gen_triton_aot.py");
    let artifact_dir = out_dir.join("triton_aot").join(spec.artifact_dir);

    let output = time_phase(format!("triton-gen {}", spec.kernel_name), || {
        Command::new(python)
            .arg(&generator_path)
            .arg("--kernel-path")
            .arg(root.join(spec.kernel_path))
            .arg("--kernel-name")
            .arg(spec.kernel_name)
            .arg("--signature")
            .arg(spec.signature)
            .arg("--grid")
            .arg(spec.grid)
            .arg("--out-name")
            .arg(spec.out_name)
            .arg("--out-dir")
            .arg(&artifact_dir)
            .arg("--target")
            .arg(triton_target)
            .arg("--num-warps")
            .arg(spec.num_warps.to_string())
            .arg("--num-stages")
            .arg(spec.num_stages.to_string())
            .output()
            .unwrap_or_else(|err| {
                panic!(
                    "failed to run Triton AOT generator for {}: {err}",
                    spec.kernel_name
                )
            })
    });

    assert!(
        output.status.success(),
        "Triton AOT generator failed for {}. stdout: {} stderr: {}",
        spec.kernel_name,
        String::from_utf8_lossy(&output.stdout).trim(),
        String::from_utf8_lossy(&output.stderr).trim(),
    );

    let stdout = String::from_utf8_lossy(&output.stdout);
    let mut func_name = None;
    let mut c_path = None;
    for line in stdout.lines() {
        if let Some(value) = line.strip_prefix("FUNC_NAME=") {
            func_name = Some(value.trim().to_string());
        } else if let Some(value) = line.strip_prefix("C_PATH=") {
            c_path = Some(PathBuf::from(value.trim()));
        }
    }

    let func_name = func_name.expect("Triton generator did not print FUNC_NAME");
    let c_path = c_path.expect("Triton generator did not print C_PATH");
    patch_triton_aot_per_device_handles(&c_path);
    (func_name, c_path)
}

fn patch_triton_aot_per_device_handles(c_path: &Path) {
    let src = fs::read_to_string(c_path).expect("failed to read generated Triton C source");
    let module_name = src
        .lines()
        .find_map(|line| line.strip_prefix("CUmodule "))
        .and_then(|rest| rest.strip_suffix(" = NULL;"))
        .map(str::to_string)
        .expect("generated Triton C source should declare one CUmodule");
    let function_name = src
        .lines()
        .find_map(|line| line.strip_prefix("CUfunction "))
        .and_then(|rest| rest.strip_suffix(" = NULL;"))
        .map(str::to_string)
        .expect("generated Triton C source should declare one CUfunction");

    let device_table_define = "#define PEGAINFER_TRITON_DEVICE_TABLE_SIZE 16\n\n";
    let device_helper = "\n\nstatic CUresult pegainfer_triton_current_device(CUdevice *dev) {\n  CUresult err = cuCtxGetDevice(dev);\n  if (err != CUDA_SUCCESS) {\n    return err;\n  }\n  if (*dev < 0 || *dev >= PEGAINFER_TRITON_DEVICE_TABLE_SIZE) {\n    return CUDA_ERROR_INVALID_DEVICE;\n  }\n  return CUDA_SUCCESS;\n}";

    let patched = src
        .replace(
            &format!("CUmodule {module_name} = NULL;"),
            &format!(
                "{device_table_define}CUmodule {module_name}[PEGAINFER_TRITON_DEVICE_TABLE_SIZE] = {{0}};"
            ),
        )
        .replace(
            &format!("CUfunction {function_name} = NULL;"),
            &format!(
                "CUfunction {function_name}[PEGAINFER_TRITON_DEVICE_TABLE_SIZE] = {{0}};{device_helper}"
            ),
        )
        .replace(
            &format!("CUDA_CHECK(cuModuleUnload({module_name}));"),
            &format!(
                "CUdevice dev = 0;\n    CUDA_CHECK(pegainfer_triton_current_device(&dev));\n    if ({module_name}[dev] != NULL) {{\n      CUDA_CHECK(cuModuleUnload({module_name}[dev]));\n      {module_name}[dev] = NULL;\n      {function_name}[dev] = NULL;\n    }}"
            ),
        );
    let patched = patched
        .replace(
            &format!("cuModuleLoadData(&{module_name}, bin)"),
            &format!("cuModuleLoadData(&{module_name}[dev], bin)"),
        )
        .replace(
            &format!("cuModuleGetFunction(&{function_name}, {module_name}, "),
            &format!("cuModuleGetFunction(&{function_name}[dev], {module_name}[dev], "),
        )
        .replace(
            &format!("cuFuncSetCacheConfig({function_name}, "),
            &format!("cuFuncSetCacheConfig({function_name}[dev], "),
        )
        .replace(
            &format!("cuFuncSetAttribute({function_name}, "),
            &format!("cuFuncSetAttribute({function_name}[dev], "),
        )
        .replace(
            &format!("if ({function_name} == NULL)\n       load_"),
            &format!("CUdevice dev = 0;\n    CUDA_CHECK(pegainfer_triton_current_device(&dev));\n    if ({function_name}[dev] == NULL)\n       load_"),
        )
        .replace(
            &format!("return cuLaunchKernel({function_name}, "),
            &format!("return cuLaunchKernel({function_name}[dev], "),
        )
        .replace(
            "int dev = 0;\n    void *bin =",
            "CUdevice dev = 0;\n    CUDA_CHECK(pegainfer_triton_current_device(&dev));\n    void *bin =",
        );

    fs::write(c_path, patched).expect("failed to patch generated Triton C source");
}

fn write_wrapper(generated_c: &Path, file_name: &str, wrapper_src: String) -> PathBuf {
    let wrapper_path = generated_c
        .parent()
        .expect("generated Triton source should have a parent directory")
        .join(file_name);
    std::fs::write(&wrapper_path, wrapper_src).expect("failed to write Triton wrapper source");
    wrapper_path
}

