113	CUresult glm52_flashinfer_sparse_mla_supported_cuda(int heads, int* supported) {
114	  if (supported == nullptr) return CUDA_ERROR_INVALID_VALUE;
115	  *supported = 0;
116	  int device = 0;
117	  cudaDeviceProp prop{};
118	  if (cudaGetDevice(&device) != cudaSuccess ||
119	      cudaGetDeviceProperties(&prop, device) != cudaSuccess) {
120	    return consume_last_cuda_error();
121	  }
122	  *supported = heads == kHeads && prop.major == 10 &&
123	               (prop.minor == 0 || prop.minor == 3);
124	  return CUDA_SUCCESS;
125	}
