135	      (tokens != 1 && tokens != 2 && tokens != 4 && tokens != 8) ||
136	      num_blocks <= 0 || (topk != 256 && topk != 2048) ||
137	      !std::isfinite(sm_scale) || sm_scale <= 0.0f ||
138	      workspace_bytes <= kCounterBytes) {
139	    return static_cast<int>(CUDA_ERROR_INVALID_VALUE);
140	  }
141	
142	  int device = 0;
143	  cudaDeviceProp prop{};
